using UnityEngine;
namespace LWS.TruckHockey {
public enum HockeyAIState {Defending,Intercepting,Approaching,Attacking,Recovering,Supporting}
public enum HockeyRole {Challenger,Support,Defender}
public sealed class HockeyAI:MonoBehaviour {
 public HockeyMatch match;public HockeyTruck truck;
 [System.Serializable]public sealed class Tuning {public float reaction=.18f,prediction=.45f,positionError=.25f,steeringError=2,defenseThreshold=.48f;}
 public Tuning easy=new Tuning{reaction=.4f,prediction=.18f,positionError=.65f,steeringError=6,defenseThreshold=.65f};public Tuning normal=new Tuning();public Tuning hard=new Tuning{reaction=.08f,prediction=.75f,positionError=.08f,steeringError=.7f,defenseThreshold=.3f};
 public HockeyAIState State{get;private set;}public HockeyRole Role{get;private set;}public Vector3 Target{get;private set;}public int Decisions{get;private set;}public int Recoveries{get;private set;}float nextDecision,stuck,recoverTimer,angleError;Vector3 previous;
 public Tuning Profile=>match.players[truck.side].difficulty==HockeyDifficulty.Easy?easy:match.players[truck.side].difficulty==HockeyDifficulty.Hard?hard:normal;
 public void ResetPlan(){nextDecision=stuck=recoverTimer=0;previous=truck.body.position;truck.ClearInput();State=HockeyAIState.Intercepting;}
 public Vector3 Predict(Vector3 p,Vector3 velocity,float time){var q=p+velocity*time;float xmax=match.goalLine-.8f,zmax=match.halfWidth-.7f;for(int i=0;i<2;i++){if(q.x>xmax)q.x=2*xmax-q.x;if(q.x< -xmax)q.x=-2*xmax-q.x;if(q.z>zmax)q.z=2*zmax-q.z;if(q.z< -zmax)q.z=-2*zmax-q.z;}q.x=Mathf.Clamp(q.x,-xmax,xmax);q.z=Mathf.Clamp(q.z,-zmax,zmax);q.y=.36f;return q;}
 void Decide(){var tuning=Profile;int own=match.rules.DefendingSign(match.TeamOf(truck.side));Vector3 goal=new Vector3(-own*match.goalLine,.36f,0);var puck=match.puck.position;var predicted=Predict(puck,match.puck.linearVelocity,tuning.prediction);var aim=(goal-predicted).normalized;Role=match.RoleFor(truck.side);
 if(Role==HockeyRole.Defender&&puck.x*own<match.goalLine*.6f){State=HockeyAIState.Defending;Target=new Vector3(own*8.5f,.36f,Mathf.Clamp(puck.z*.4f,-2.2f,2.2f));}
 else if(Role==HockeyRole.Support&&Vector3.Distance(truck.body.position,puck)>2.7f){State=HockeyAIState.Supporting;float wing=puck.z>0?-1:1;Target=predicted+new Vector3(own*3,.36f-predicted.y,wing*2.8f);}
 else {bool threat=puck.x*own>match.goalLine*tuning.defenseThreshold&&(match.puck.linearVelocity.x*own>-.8f||puck.x*own>match.goalLine*.75f);
 if(threat){State=HockeyAIState.Defending;bool goalSide=(truck.body.position.x-predicted.x)*own>.8f;Target=goalSide?predicted-new Vector3(own*.8f,0,0):predicted+new Vector3(own*1.8f,0,(truck.body.position.z>=predicted.z?1:-1)*2.1f);}
 else{float ahead=Vector3.Dot(truck.body.position-predicted,aim);var behind=predicted-aim*1.8f;if(ahead>-.6f){State=HockeyAIState.Approaching;float lateral=Vector3.Dot(truck.body.position-predicted,Vector3.Cross(Vector3.up,aim));behind+=Vector3.Cross(Vector3.up,aim)*(lateral>=0?1.6f:-1.6f);Target=behind;}else if(Vector3.Distance(truck.body.position,puck)<3.2f){State=HockeyAIState.Attacking;Target=predicted+aim*1.2f;}else{State=HockeyAIState.Intercepting;Target=behind;}}}
 Target+=new Vector3(Random.Range(-tuning.positionError,tuning.positionError),0,Random.Range(-tuning.positionError,tuning.positionError));Target=new Vector3(Mathf.Clamp(Target.x,-match.goalLine+1.4f,match.goalLine-1.4f),.36f,Mathf.Clamp(Target.z,-match.halfWidth+1.4f,match.halfWidth-1.4f));angleError=Random.Range(-tuning.steeringError,tuning.steeringError);Decisions++;nextDecision=Time.time+tuning.reaction;}
 void FixedUpdate(){if(!match.InMatch||match.MenuOpen||!match.rules.Live||!match.IsAI(truck.side)){truck.ClearInput();return;}float dt=Time.fixedDeltaTime;if(State==HockeyAIState.Recovering){recoverTimer-=dt;truck.Control(-.55f,(truck.side%2==0?1:-1)*.65f,false);if(recoverTimer<=0){stuck=0;nextDecision=0;State=HockeyAIState.Intercepting;}return;}
 if(Vector3.Distance(truck.body.position,previous)<.018f&&Mathf.Abs(truck.throttle)>.3f)stuck+=dt;else stuck=Mathf.Max(0,stuck-dt*.4f);previous=truck.body.position;if(stuck>1.8f){State=HockeyAIState.Recovering;Recoveries++;recoverTimer=1.1f;return;}if(Time.time>=nextDecision)Decide();Vector3 delta=Target-truck.body.position;delta.y=0;if(delta.magnitude<.45f&&(Role!=HockeyRole.Challenger)){truck.Control(0,0,false);return;}float angle=Vector3.SignedAngle(truck.transform.forward,delta,Vector3.up)+angleError;bool reverse=Mathf.Abs(angle)>110;if(reverse)angle=Mathf.DeltaAngle(0,angle-180);float throttle=Mathf.Clamp(delta.magnitude*.5f,.15f,State==HockeyAIState.Attacking?.95f:.75f);truck.Control((reverse?-1:1)*throttle,Mathf.Clamp(angle/35,-1,1)*(reverse?-1:1),false);}
}
}